<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';import {Head,Link,router,useForm} from '@inertiajs/vue3';import {Eye,Plus,RotateCcw,Search} from 'lucide-vue-next';import {ref,watch} from 'vue';
const p=defineProps<{projects:any;filters:any}>();const filters=ref({search:p.filters.search??'',status:p.filters.status??'',responsible:p.filters.responsible??''});const showCreate=ref(false);const create=useForm({code:'',name:''});let timer:any;
function apply(){router.get(route('admin.projects.index'),filters.value,{preserveState:true,preserveScroll:true,replace:true})}watch(()=>filters.value.search,()=>{clearTimeout(timer);timer=setTimeout(apply,350)});watch([()=>filters.value.status,()=>filters.value.responsible],apply);function reset(){filters.value={search:'',status:'',responsible:''};apply()}function submit(){create.post(route('admin.projects.store'),{preserveScroll:true,onSuccess:()=>{create.reset();showCreate.value=false}})}
</script>
<template><Head title="Chantiers"/><AppLayout :breadcrumbs="[{title:'Administration',href:'#'},{title:'Chantiers',href:route('admin.projects.index')}]"><div class="space-y-6 p-6 lg:p-8">
<header class="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><h1 class="text-3xl font-bold text-slate-950">Chantiers</h1><p class="mt-1 text-slate-600">Consultez les activités et gérez les responsables dans le temps.</p></div><button class="btn-dark" @click="showCreate=!showCreate"><Plus class="h-4 w-4"/> Nouveau chantier</button></header>
<form v-if="showCreate" class="grid gap-4 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm md:grid-cols-[1fr_2fr_auto]" @submit.prevent="submit"><div><label class="label">Code</label><input v-model="create.code" required class="field" placeholder="Ex. CH-001"><p v-if="create.errors.code" class="error">{{create.errors.code}}</p></div><div><label class="label">Nom du chantier</label><input v-model="create.name" required class="field" placeholder="Nom du chantier"><p v-if="create.errors.name" class="error">{{create.errors.name}}</p></div><button class="mt-6 h-11 rounded-xl bg-amber-600 px-5 font-semibold text-white">Créer</button></form>
<section class="rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="grid gap-3 border-b border-slate-200 p-4 lg:grid-cols-[2fr_1fr_1fr_auto]"><div class="relative"><Search class="absolute left-3 top-3.5 h-4 w-4 text-slate-500"/><input v-model="filters.search" class="field !pl-9" placeholder="Rechercher par code ou nom…"></div><select v-model="filters.status" class="field"><option value="">Tous les statuts</option><option value="active">Actifs</option><option value="inactive">Inactifs</option></select><select v-model="filters.responsible" class="field"><option value="">Tous les responsables</option><option value="assigned">Avec responsable</option><option value="unassigned">Sans responsable</option></select><button class="btn-light" @click="reset"><RotateCcw class="h-4 w-4"/> Réinitialiser</button></div>
<div class="overflow-x-auto"><table class="w-full min-w-[850px] text-left"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-700"><tr><th class="cell">Chantier</th><th class="cell">Responsable actuel</th><th class="cell">Statut</th><th class="cell text-center">Bons de commande</th><th class="cell text-center">Transferts</th><th class="cell text-right">Action</th></tr></thead><tbody class="divide-y divide-slate-200"><tr v-for="project in projects.data" :key="project.id" class="hover:bg-slate-50"><td class="cell"><strong class="block text-slate-950">{{project.name}}</strong><span class="text-sm text-slate-600">{{project.code}}</span></td><td class="cell"><template v-if="project.current_responsible_assignment"><strong class="block text-sm text-slate-950">{{project.current_responsible_assignment.user?.name}}</strong><span class="text-xs text-slate-600">Depuis le {{new Date(project.current_responsible_assignment.starts_at).toLocaleDateString('fr-FR')}}</span></template><span v-else class="rounded-full bg-amber-100 px-3 py-1 text-xs font-semibold text-amber-900">Non affecté</span></td><td class="cell"><span class="rounded-full px-3 py-1 text-xs font-semibold" :class="project.is_active?'bg-emerald-100 text-emerald-800':'bg-slate-200 text-slate-800'">{{project.is_active?'Actif':'Inactif'}}</span></td><td class="cell text-center font-semibold text-slate-950">{{project.purchase_orders_count}}</td><td class="cell text-center font-semibold text-slate-950">{{project.reception_transfers_count}}</td><td class="cell text-right"><Link :href="route('admin.projects.show',project.id)" class="inline-flex items-center gap-2 rounded-lg px-3 py-2 text-sm font-semibold text-amber-700 hover:bg-amber-50"><Eye class="h-4 w-4"/> Consulter</Link></td></tr><tr v-if="!projects.data.length"><td colspan="6" class="px-5 py-16 text-center"><strong class="text-slate-950">Aucun chantier trouvé</strong><p class="text-sm text-slate-600">Modifiez les filtres ou créez un chantier.</p></td></tr></tbody></table></div>
<div v-if="projects.links?.length>3" class="flex flex-wrap items-center justify-between gap-3 border-t border-slate-200 p-4"><p class="text-sm text-slate-600">{{projects.from}}–{{projects.to}} sur {{projects.total}}</p><div class="flex gap-1"><Link v-for="l in projects.links" :key="l.label" :href="l.url||'#'" preserve-scroll preserve-state class="min-w-9 rounded-lg border px-3 py-2 text-center text-sm" :class="[l.active?'border-slate-950 bg-slate-950 text-white':'border-slate-300 text-slate-800',!l.url?'pointer-events-none opacity-40':'']" v-html="l.label"/></div></div></section></div></AppLayout></template>
<style scoped>.field{height:2.75rem;width:100%;border-radius:.75rem;border:1px solid #cbd5e1;background:#fff;padding:0 .85rem;color:#020617;outline:none}.field::placeholder{color:#64748b}.field:focus{border-color:#d97706;box-shadow:0 0 0 3px #d977061f}.label{margin-bottom:.25rem;display:block;font-size:.875rem;font-weight:500;color:#1e293b}.error{font-size:.75rem;color:#dc2626}.btn-dark,.btn-light{display:inline-flex;height:2.75rem;align-items:center;justify-content:center;gap:.5rem;border-radius:.75rem;padding:0 1rem;font-weight:600}.btn-dark{background:#020617;color:white}.btn-light{border:1px solid #cbd5e1;color:#1e293b}.cell{padding:1rem 1.25rem}</style>